'use strict';

/**
 * Tests for the LIVE Vertex AI image adapter (Task #3). These run fully
 * offline: Node 22's global `fetch` is stubbed per-test and the OAuth token is
 * injected via process.env, so no real network call is ever made.
 *
 * The suite asserts the live path targets only the Google Vertex AI endpoint,
 * returns the generated bytes as a data URL, and falls back to the
 * deterministic mock composite on a missing token or an HTTP/transport failure
 * (so the try-on flow never breaks).
 */

const { test } = require('node:test');
const assert = require('node:assert');

const { loadConfig } = require('../src/config');
const { createVertexImage } = require('../src/adapters/vertexImage');

const LIVE_CONFIG = loadConfig({ VERTEX_IMAGE_MODE: 'live' });

/** Stub global.fetch to look like a Vertex AI :predict response. */
function stubFetch(b64, { ok = true, status = 200, throwTransport = false } = {}) {
  const original = globalThis.fetch;
  const calls = [];
  globalThis.fetch = async (url, options) => {
    calls.push({ url, options });
    if (throwTransport) throw new Error('simulated network failure');
    return {
      ok,
      status,
      async json() { return { predictions: [{ bytesBase64Encoded: b64 }] }; },
    };
  };
  return { restore: () => { globalThis.fetch = original; }, calls };
}

/** Run `fn` with GOOGLE_ACCESS_TOKEN set, restoring the env afterwards. */
async function withToken(token, fn) {
  const prev = process.env.GOOGLE_ACCESS_TOKEN;
  process.env.GOOGLE_ACCESS_TOKEN = token;
  try { return await fn(); }
  finally {
    if (prev === undefined) delete process.env.GOOGLE_ACCESS_TOKEN;
    else process.env.GOOGLE_ACCESS_TOKEN = prev;
  }
}

test('live generateTryOn returns generated bytes as a data URL and targets Vertex AI', async () => {
  const stub = stubFetch('AAABBBCCC');
  try {
    await withToken('ya29.test-token', async () => {
      const vertex = createVertexImage({ mode: 'live', config: LIVE_CONFIG });
      const res = await vertex.generateTryOn({ skus: ['TOP-LIN-001', 'BOT-SHT-010'] });
      assert.strictEqual(res.source, 'vertex-image-live');
      assert.strictEqual(res.imageDataUrl, 'data:image/png;base64,AAABBBCCC');
      assert.strictEqual(res.isComposite, true);
      assert.ok(res.disclaimer.length > 0);
      assert.deepStrictEqual(res.skus, ['TOP-LIN-001', 'BOT-SHT-010']);

      assert.strictEqual(stub.calls.length, 1);
      const { url, options } = stub.calls[0];
      assert.ok(url.includes('-aiplatform.googleapis.com/'), 'must call only the Google Vertex AI endpoint');
      assert.ok(url.endsWith(':predict'));
      assert.strictEqual(options.method, 'POST');
      assert.strictEqual(options.headers.Authorization, 'Bearer ya29.test-token');
    });
  } finally {
    stub.restore();
  }
});

test('live generateTryOn with NO token falls back to the deterministic mock', async () => {
  const stub = stubFetch('AAA');
  try {
    // Ensure neither token env var is set.
    const prevA = process.env.GOOGLE_ACCESS_TOKEN;
    const prevB = process.env.GOOGLE_OAUTH_TOKEN;
    delete process.env.GOOGLE_ACCESS_TOKEN;
    delete process.env.GOOGLE_OAUTH_TOKEN;
    try {
      const vertex = createVertexImage({ mode: 'live', config: LIVE_CONFIG });
      const res = await vertex.generateTryOn({ skus: ['TOP-LIN-001'] });
      assert.strictEqual(res.source, 'vertex-image-mock');
      assert.strictEqual(res.imageDataUrl, null);
      assert.strictEqual(res.isComposite, true);
      assert.strictEqual(stub.calls.length, 0, 'no fetch without a token');
    } finally {
      if (prevA !== undefined) process.env.GOOGLE_ACCESS_TOKEN = prevA;
      if (prevB !== undefined) process.env.GOOGLE_OAUTH_TOKEN = prevB;
    }
  } finally {
    stub.restore();
  }
});

test('live generateTryOn falls back to mock on HTTP failure', async () => {
  const stub = stubFetch('AAA', { ok: false, status: 500 });
  try {
    await withToken('ya29.test-token', async () => {
      const vertex = createVertexImage({ mode: 'live', config: LIVE_CONFIG });
      const res = await vertex.generateTryOn({ skus: ['TOP-LIN-001'] });
      assert.strictEqual(res.source, 'vertex-image-mock');
      assert.strictEqual(res.imageDataUrl, null);
    });
  } finally {
    stub.restore();
  }
});

test('live generateTryOn falls back to mock on transport error', async () => {
  const stub = stubFetch(null, { throwTransport: true });
  try {
    await withToken('ya29.test-token', async () => {
      const vertex = createVertexImage({ mode: 'live', config: LIVE_CONFIG });
      const res = await vertex.generateTryOn({ skus: ['TOP-LIN-001'] });
      assert.strictEqual(res.source, 'vertex-image-mock');
    });
  } finally {
    stub.restore();
  }
});

test('mock generateTryOn returns the deterministic offline composite (no data URL)', async () => {
  const vertex = createVertexImage({ mode: 'mock', config: LIVE_CONFIG });
  const res = await vertex.generateTryOn({ skus: ['TOP-LIN-001', 'BOT-SHT-010'] });
  assert.strictEqual(res.source, 'vertex-image-mock');
  assert.strictEqual(res.imageDataUrl, null);
  assert.ok(res.localRef.startsWith('/assets/tryon/'));
  assert.ok(res.imageRef.startsWith('gs://'));
});
